[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <meta name="description" content="Unique flavors, quality ingredients, and unbeatable prices — all waiting for you at your neighborhood Fresh Pantry.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Nunito:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --primary: #2D6A4F;
      --primary-light: #40916C;
      --primary-dark: #1B4332;
      --accent: #F4A261;
      --accent-dark: #D97706;
      --terracotta: #E07A5F;
      --cream: #FEFAE0;
      --cream-dark: #F5ECC7;
      --bg: #FEFAE0;
      --card: #FFFFFF;
      --text: #1E293B;
      --text-secondary: #475569;
      --muted: #64748B;
      --border: #D8E8DF;
      --shadow-sm: 0 1px 3px rgba(45,106,79,0.08);
      --shadow-md: 0 4px 12px rgba(45,106,79,0.1);
      --shadow-lg: 0 8px 30px rgba(45,106,79,0.12);
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --font-heading: 'Fredoka', sans-serif;
      --font-body: 'Nunito', sans-serif;
      --transition: 250ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      font-size: 16px;
      line-height: 1.6;
      color: var(--text);
      background: var(--bg);
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); line-height: 1.2; }

    a { text-decoration: none; color: inherit; }
    img { max-width: 100%; display: block; }
    button { font-family: var(--font-body); cursor: pointer; border: none; }
    input { font-family: var(--font-body); }

    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

    /* Skip link */
    .skip-link {
      position: absolute; top: -100%; left: 50%; transform: translateX(-50%);
      background: var(--primary); color: #fff; padding: 12px 24px; border-radius: var(--radius-sm);
      z-index: 10000; font-weight: 600; transition: top var(--transition);
    }
    .skip-link:focus { top: 12px; }

    /* ===== HEADER ===== */
    .header {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      background: rgba(254,250,224,0.92); backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      transition: box-shadow var(--transition);
    }
    .header.scrolled { box-shadow: var(--shadow-md); }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 72px; max-width: 1200px; margin: 0 auto; padding: 0 24px;
    }
    .logo {
      display: flex; align-items: center; gap: 10px;
      font-family: var(--font-heading); font-size: 1.5rem; font-weight: 700;
      color: var(--primary);
    }
    .logo-icon {
      width: 40px; height: 40px; background: var(--primary); border-radius: var(--radius-sm);
      display: flex; align-items: center; justify-content: center;
    }
    .logo-icon svg { width: 24px; height: 24px; }
    .nav-links { display: flex; align-items: center; gap: 8px; list-style: none; }
    .nav-links a {
      padding: 8px 18px; border-radius: var(--radius-xl); font-weight: 600;
      font-size: 0.95rem; color: var(--primary-dark); transition: all var(--transition);
    }
    .nav-links a:hover, .nav-links a:focus-visible {
      background: var(--primary); color: #fff;
    }
    .nav-links a:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
    .mobile-toggle {
      display: none; background: none; padding: 8px;
      color: var(--primary-dark); border-radius: var(--radius-sm);
    }
    .mobile-toggle svg { width: 28px; height: 28px; }

    @media (max-width: 768px) {
      .nav-links {
        display: none; position: absolute; top: 72px; left: 0; right: 0;
        flex-direction: column; background: var(--cream); padding: 16px 24px;
        border-bottom: 1px solid var(--border); gap: 4px;
        box-shadow: var(--shadow-md);
      }
      .nav-links.open { display: flex; }
      .nav-links a { padding: 14px 18px; font-size: 1.05rem; }
      .mobile-toggle { display: flex; }
    }

    /* ===== HERO ===== */
    .hero {
      padding: 140px 0 80px; position: relative; overflow: hidden;
      background: linear-gradient(135deg, var(--cream) 0%, #E8F5E9 50%, var(--cream) 100%);
    }
    .hero::before {
      content: ''; position: absolute; top: -60px; right: -60px;
      width: 300px; height: 300px; border-radius: 50%;
      background: radial-gradient(circle, rgba(244,162,97,0.15), transparent 70%);
    }
    .hero::after {
      content: ''; position: absolute; bottom: -40px; left: -40px;
      width: 250px; height: 250px; border-radius: 50%;
      background: radial-gradient(circle, rgba(45,106,79,0.1), transparent 70%);
    }
    .hero-inner {
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
      position: relative; z-index: 1;
    }
    .hero-text h1 {
      font-size: 3.5rem; font-weight: 700; color: var(--primary-dark);
      margin-bottom: 20px; line-height: 1.1;
    }
    .hero-text h1 span { color: var(--accent-dark); }
    .hero-text p {
      font-size: 1.2rem; color: var(--text-secondary); margin-bottom: 32px;
      max-width: 520px; line-height: 1.7;
    }
    .hero-ctas { display: flex; gap: 16px; flex-wrap: wrap; }
    .btn {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 14px 28px; border-radius: var(--radius-xl);
      font-weight: 700; font-size: 1rem; transition: all var(--transition);
      cursor: pointer;
    }
    .btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
    .btn-primary { background: var(--primary); color: #fff; }
    .btn-primary:hover { background: var(--primary-light); transform: translateY(-2px); box-shadow: var(--shadow-md); }
    .btn-secondary { background: #fff; color: var(--primary); border: 2px solid var(--primary); }
    .btn-secondary:hover { background: var(--primary); color: #fff; transform: translateY(-2px); }
    .btn-accent { background: var(--accent); color: var(--primary-dark); }
    .btn-accent:hover { background: var(--accent-dark); color: #fff; transform: translateY(-2px); box-shadow: var(--shadow-md); }

    .hero-visual {
      display: flex; justify-content: center; align-items: center;
      position: relative;
    }
    .hero-image-group {
      position: relative; width: 100%; max-width: 460px; aspect-ratio: 1;
    }
    .hero-img-main {
      width: 85%; border-radius: var(--radius-lg); box-shadow: var(--shadow-lg);
      object-fit: cover; aspect-ratio: 4/5; position: relative; z-index: 2;
      background: linear-gradient(135deg, #C8E6C9, #A5D6A7);
    }
    .hero-img-accent {
      position: absolute; bottom: 0; right: 0; width: 50%; border-radius: var(--radius-md);
      box-shadow: var(--shadow-md); object-fit: cover; aspect-ratio: 1;
      z-index: 3; border: 4px solid #fff;
      background: linear-gradient(135deg, #FFE0B2, #FFCC80);
    }
    .hero-badge {
      position: absolute; top: 10px; right: -10px; background: var(--accent);
      color: var(--primary-dark); padding: 12px 20px; border-radius: var(--radius-md);
      font-family: var(--font-heading); font-weight: 700; font-size: 1.1rem;
      box-shadow: var(--shadow-md); z-index: 4;
      animation: float 3s ease-in-out infinite;
    }
    @keyframes float {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-8px); }
    }

    @media (max-width: 768px) {
      .hero { padding: 120px 0 60px; }
      .hero-inner { grid-template-columns: 1fr; text-align: center; }
      .hero-text h1 { font-size: 2.4rem; }
      .hero-text p { margin-left: auto; margin-right: auto; }
      .hero-ctas { justify-content: center; }
      .hero-visual { margin-top: 40px; }
      .hero-image-group { max-width: 320px; }
    }

    /* ===== SECTION COMMON ===== */
    .section { padding: 80px 0; }
    .section-header { text-align: center; margin-bottom: 48px; }
    .section-header h2 { font-size: 2.2rem; color: var(--primary-dark); margin-bottom: 12px; }
    .section-header p { font-size: 1.1rem; color: var(--muted); max-width: 560px; margin: 0 auto; }

    /* ===== FEATURED PRODUCTS CAROUSEL ===== */
    .featured { background: #fff; }
    .carousel-wrapper { position: relative; overflow: hidden; }
    .carousel-track {
      display: flex; gap: 24px; transition: transform 400ms cubic-bezier(0.25, 0.46, 0.45, 0.94);
      padding: 8px 4px 16px;
    }
    .product-card {
      flex: 0 0 calc(25% - 18px); background: var(--cream); border-radius: var(--radius-md);
      overflow: hidden; transition: all var(--transition); cursor: pointer;
      box-shadow: var(--shadow-sm);
    }
    .product-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }
    .product-card-img {
      width: 100%; aspect-ratio: 1; object-fit: cover;
      background: linear-gradient(135deg, #E8F5E9, #C8E6C9);
      display: flex; align-items: center; justify-content: center;
    }
    .product-card-img svg { width: 56px; height: 56px; opacity: 0.4; }
    .product-card-body { padding: 20px; }
    .product-card-body h3 { font-size: 1.05rem; font-weight: 600; color: var(--primary-dark); margin-bottom: 6px; }
    .product-card-body p { font-size: 0.88rem; color: var(--muted); margin-bottom: 12px; line-height: 1.5; }
    .product-card-price {
      font-family: var(--font-heading); font-weight: 700; font-size: 1.15rem;
      color: var(--accent-dark);
    }

    .carousel-btn {
      position: absolute; top: 50%; transform: translateY(-50%); z-index: 10;
      width: 48px; height: 48px; border-radius: 50%; background: #fff;
      box-shadow: var(--shadow-md); display: flex; align-items: center; justify-content: center;
      transition: all var(--transition); border: 2px solid var(--border);
      color: var(--primary);
    }
    .carousel-btn:hover { background: var(--primary); color: #fff; border-color: var(--primary); }
    .carousel-btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
    .carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }
    .carousel-btn:disabled:hover { background: #fff; color: var(--primary); border-color: var(--border); }
    .carousel-btn-prev { left: -8px; }
    .carousel-btn-next { right: -8px; }
    .carousel-btn svg { width: 22px; height: 22px; }

    @media (max-width: 1024px) { .product-card { flex: 0 0 calc(33.333% - 16px); } }
    @media (max-width: 768px) {
      .product-card { flex: 0 0 calc(50% - 12px); }
      .carousel-btn { width: 40px; height: 40px; }
      .carousel-btn-prev { left: 0; }
      .carousel-btn-next { right: 0; }
    }
    @media (max-width: 480px) { .product-card { flex: 0 0 calc(100% - 0px); } }

    /* ===== SEASONAL PICKS ===== */
    .seasonal {
      background: linear-gradient(135deg, #FFF8E1 0%, var(--cream) 100%);
      position: relative;
    }
    .seasonal-grid {
      display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 24px;
    }
    .seasonal-card {
      background: #fff; border-radius: var(--radius-md); padding: 24px;
      display: flex; gap: 18px; align-items: flex-start;
      box-shadow: var(--shadow-sm); transition: all var(--transition);
    }
    .seasonal-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
    .seasonal-icon {
      flex-shrink: 0; width: 56px; height: 56px; border-radius: var(--radius-sm);
      display: flex; align-items: center; justify-content: center;
      background: linear-gradient(135deg, #FFF3E0, #FFE0B2);
    }
    .seasonal-icon svg { width: 28px; height: 28px; color: var(--accent-dark); }
    .seasonal-card h3 { font-size: 1rem; font-weight: 600; color: var(--primary-dark); margin-bottom: 4px; }
    .seasonal-card p { font-size: 0.88rem; color: var(--muted); margin-bottom: 8px; }
    .seasonal-price { font-family: var(--font-heading); font-weight: 700; color: var(--accent-dark); font-size: 1.05rem; }

    /* ===== CATEGORIES ===== */
    .categories { background: #fff; }
    .category-grid {
      display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 20px;
    }
    .category-card {
      position: relative; border-radius: var(--radius-md); overflow: hidden;
      aspect-ratio: 4/3; cursor: pointer; transition: transform var(--transition);
    }
    .category-card:hover { transform: scale(1.04); }
    .category-bg {
      width: 100%; height: 100%; object-fit: cover;
      background-size: cover; background-position: center;
      transition: transform 400ms ease;
    }
    .category-card:hover .category-bg { transform: scale(1.08); }
    .category-overlay {
      position: absolute; inset: 0; background: linear-gradient(to top, rgba(27,67,50,0.7) 0%, rgba(27,67,50,0.2) 60%, transparent 100%);
      display: flex; flex-direction: column; justify-content: flex-end;
      padding: 24px; transition: all var(--transition);
    }
    .category-card:hover .category-overlay {
      background: linear-gradient(to top, rgba(27,67,50,0.85) 0%, rgba(27,67,50,0.45) 60%, rgba(27,67,50,0.15) 100%);
    }
    .category-overlay h3 { color: #fff; font-size: 1.2rem; font-weight: 700; }
    .category-overlay p { color: rgba(255,255,255,0.8); font-size: 0.85rem; margin-top: 4px; opacity: 0; transform: translateY(8px); transition: all var(--transition); }
    .category-card:hover .category-overlay p { opacity: 1; transform: translateY(0); }
    .category-card:focus-within { outline: 3px solid var(--accent); outline-offset: 2px; }

    /* category bg colors */
    .cat-snacks { background: linear-gradient(135deg, #FFCC80, #FFB74D); }
    .cat-produce { background: linear-gradient(135deg, #A5D6A7, #81C784); }
    .cat-frozen { background: linear-gradient(135deg, #90CAF9, #64B5F6); }
    .cat-beverages { background: linear-gradient(135deg, #EF9A9A, #E57373); }
    .cat-dairy { background: linear-gradient(135deg, #FFF59D, #FFF176); }

    /* ===== BRAND HIGHLIGHTS ===== */
    .highlights {
      background: var(--primary); color: #fff; padding: 64px 0;
      position: relative; overflow: hidden;
    }
    .highlights::before {
      content: ''; position: absolute; top: -50%; left: -10%;
      width: 400px; height: 400px; border-radius: 50%;
      background: rgba(255,255,255,0.04);
    }
    .highlights::after {
      content: ''; position: absolute; bottom: -40%; right: -5%;
      width: 350px; height: 350px; border-radius: 50%;
      background: rgba(255,255,255,0.03);
    }
    .highlights-grid {
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px;
      position: relative; z-index: 1;
    }
    .highlight-item { text-align: center; }
    .highlight-number {
      font-family: var(--font-heading); font-size: 2.8rem; font-weight: 700;
      color: var(--accent); margin-bottom: 8px;
    }
    .highlight-label { font-size: 1rem; font-weight: 600; margin-bottom: 4px; }
    .highlight-desc { font-size: 0.88rem; color: rgba(255,255,255,0.7); }

    @media (max-width: 768px) {
      .highlights-grid { grid-template-columns: repeat(2, 1fr); gap: 28px; }
      .highlight-number { font-size: 2.2rem; }
    }

    /* ===== STORE LOCATOR ===== */
    .store-locator { background: var(--cream); }
    .locator-form {
      display: flex; gap: 12px; max-width: 480px; margin: 0 auto 36px;
      flex-wrap: wrap; justify-content: center;
    }
    .locator-input {
      flex: 1; min-width: 200px; padding: 14px 20px;
      border: 2px solid var(--border); border-radius: var(--radius-xl);
      font-size: 1rem; background: #fff; color: var(--text);
      transition: border-color var(--transition);
    }
    .locator-input:focus { outline: none; border-color: var(--primary); }
    .locator-input::placeholder { color: var(--muted); }
    .locator-btn {
      padding: 14px 28px; background: var(--primary); color: #fff;
      border-radius: var(--radius-xl); font-weight: 700; font-size: 1rem;
      transition: all var(--transition);
    }
    .locator-btn:hover { background: var(--primary-light); transform: translateY(-2px); box-shadow: var(--shadow-md); }
    .locator-btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
    .store-results { max-width: 700px; margin: 0 auto; }
    .store-result {
      background: #fff; border-radius: var(--radius-md); padding: 24px;
      margin-bottom: 16px; box-shadow: var(--shadow-sm);
      display: grid; grid-template-columns: 1fr auto; gap: 12px;
      align-items: start; transition: all var(--transition);
      animation: slideUp 300ms ease both;
    }
    .store-result:hover { box-shadow: var(--shadow-md); }
    .store-result h3 { font-size: 1.1rem; font-weight: 600; color: var(--primary-dark); margin-bottom: 6px; }
    .store-result p { font-size: 0.9rem; color: var(--muted); }
    .store-distance {
      background: var(--cream); color: var(--primary); padding: 8px 16px;
      border-radius: var(--radius-xl); font-weight: 700; font-size: 0.9rem;
      white-space: nowrap; font-family: var(--font-heading);
    }
    @keyframes slideUp {
      from { opacity: 0; transform: translateY(16px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .store-results:empty { display: none; }

    /* ===== NEWSLETTER ===== */
    .newsletter {
      background: linear-gradient(135deg, #E8F5E9, var(--cream));
      text-align: center;
    }
    .newsletter-icon { margin: 0 auto 16px; width: 56px; height: 56px; }
    .newsletter-icon svg { width: 56px; height: 56px; color: var(--accent-dark); }
    .newsletter-form {
      display: flex; gap: 12px; max-width: 460px; margin: 28px auto 0;
      flex-wrap: wrap; justify-content: center;
    }
    .newsletter-input {
      flex: 1; min-width: 220px; padding: 14px 20px;
      border: 2px solid var(--border); border-radius: var(--radius-xl);
      font-size: 1rem; background: #fff; color: var(--text);
      transition: border-color var(--transition);
    }
    .newsletter-input:focus { outline: none; border-color: var(--primary); }
    .newsletter-input::placeholder { color: var(--muted); }
    .newsletter-submit {
      padding: 14px 28px; background: var(--accent); color: var(--primary-dark);
      border-radius: var(--radius-xl); font-weight: 700; font-size: 1rem;
      transition: all var(--transition);
    }
    .newsletter-submit:hover { background: var(--accent-dark); color: #fff; transform: translateY(-2px); box-shadow: var(--shadow-md); }
    .newsletter-submit:focus-visible { outline: 3px solid var(--primary); outline-offset: 2px; }
    .newsletter-confirm {
      margin-top: 16px; font-weight: 600; color: var(--primary);
      display: none; animation: slideUp 300ms ease both;
    }
    .newsletter-confirm.show { display: block; }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--primary-dark); color: rgba(255,255,255,0.85);
      padding: 60px 0 32px;
    }
    .footer-grid {
      display: grid; grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 40px; margin-bottom: 40px;
    }
    .footer-brand p { margin-top: 12px; font-size: 0.9rem; line-height: 1.7; color: rgba(255,255,255,0.6); max-width: 280px; }
    .footer h4 { color: #fff; font-size: 1rem; margin-bottom: 16px; }
    .footer ul { list-style: none; }
    .footer li { margin-bottom: 10px; }
    .footer a { color: rgba(255,255,255,0.6); font-size: 0.9rem; transition: color var(--transition); }
    .footer a:hover { color: var(--accent); }
    .footer-social { display: flex; gap: 12px; margin-top: 16px; }
    .footer-social a {
      width: 40px; height: 40px; border-radius: 50%; background: rgba(255,255,255,0.1);
      display: flex; align-items: center; justify-content: center; transition: all var(--transition);
    }
    .footer-social a:hover { background: var(--accent); color: var(--primary-dark); }
    .footer-social svg { width: 18px; height: 18px; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px;
      text-align: center; font-size: 0.85rem; color: rgba(255,255,255,0.4);
    }

    @media (max-width: 768px) {
      .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
    }
    @media (max-width: 480px) {
      .footer-grid { grid-template-columns: 1fr; }
    }

    /* ===== REDUCED MOTION ===== */
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
      html { scroll-behavior: auto; }
    }
  </style>
</head>
<body>
  <a href="#main" class="skip-link">Skip to main content</a>

  <!-- ===== HEADER ===== -->
  <header class="header" role="banner">
    <div class="header-inner">
      <a href="/" class="logo" aria-label="Fresh Pantry Home">
        <span class="logo-icon">
          <svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10 10-4.5 10-10S17.5 2 12 2"/><path d="M12 6v6l4 2"/></svg>
        </span>
        Fresh Pantry
      </a>
      <nav aria-label="Main navigation">
        <ul class="nav-links" id="navLinks" role="menubar">
          <li role="none"><a href="#featured" role="menuitem">Products</a></li>
          <li role="none"><a href="#store-locator" role="menuitem">Our Stores</a></li>
          <li role="none"><a href="#seasonal" role="menuitem">Recipes</a></li>
